// Anchor Merkle batches to Solana for
// tamper-proof provenance claims.
#[program]
pub fn anchor_batch(ctx: Context<AnchorBatch>, root: [u8; 32], count: u64) -> Result<()> {
    let batch = &mut ctx.accounts.batch;
    batch.root = root;
    batch.count = count;
    batch.timestamp = Clock::get()?.unix_timestamp;
    Ok(())
}
